<?php
 namespace Pterodactyl\Services\Dezerx\FiveM; use Throwable; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Http; class Artifacts { public const LISTING = 'https://runtime.fivem.net/artifacts/fivem/build_proot_linux/master/'; public const CHANNELS = 'https://changelogs-live.fivem.net/api/changelog/versions/linux/server'; private const AGENT = 'Pterodactyl-Stark/1.0 (fivem utils)'; private const TTL = 1800; private const ARTIFACT = '#build_proot_linux/master/(\d+)-([0-9a-f]+)/fx\.tar\.xz#'; public function catalogue(): array { $builds = $this->builds(); return [ 'builds' => $builds, 'channels' => $this->channels(), 'error' => $builds === [] ? 'The FiveM artifact server could not be reached.' : null, ]; } public function builds(): array { return Cache::remember('fivem:builds', self::TTL, function () { $refs = []; try { $response = Http::withHeaders(['User-Agent' => self::AGENT])->timeout(25)->get(self::LISTING); if ($response->ok()) { foreach ($this->extract($response->body()) as $build => $ref) { $refs[$build] = $ref; } } } catch (Throwable) { } foreach ($this->extract(implode(' ', $this->downloadUrls())) as $build => $ref) { $refs[$build] = $ref; } if ($refs === []) { return []; } $dates = $this->supportPolicy(); $builds = array_map( static fn (array $ref) => $ref + ['published' => $dates[$ref['build']] ?? null], array_values($refs), ); usort($builds, static fn (array $a, array $b) => (int) $b['build'] <=> (int) $a['build']); return $builds; }); } public function channels(): array { $json = $this->changelog(); return array_filter([ 'latest' => (string) ($json['latest'] ?? ''), 'recommended' => (string) ($json['recommended'] ?? ''), 'critical' => (string) ($json['critical'] ?? ''), 'optional' => (string) ($json['optional'] ?? ''), 'latestTxAdmin' => (string) ($json['latest_txadmin'] ?? ''), 'recommendedTxAdmin' => (string) ($json['recommended_txadmin'] ?? ''), ], fn (string $value) => $value !== ''); } public function build(string $number): ?array { foreach ($this->builds() as $build) { if ($build['build'] === $number) { return $build; } } return null; } private function changelog(): array { return Cache::remember('fivem:changelog', self::TTL, function () { try { $response = Http::withHeaders(['User-Agent' => self::AGENT])->timeout(15)->get(self::CHANNELS); return $response->ok() ? (array) ($response->json() ?? []) : []; } catch (Throwable) { return []; } }); } private function downloadUrls(): array { $json = $this->changelog(); return array_values(array_filter([ (string) ($json['latest_download'] ?? ''), (string) ($json['recommended_download'] ?? ''), (string) ($json['critical_download'] ?? ''), (string) ($json['optional_download'] ?? ''), ], fn (string $value) => $value !== '')); } private function supportPolicy(): array { $policy = (array) ($this->changelog()['support_policy'] ?? []); $dates = []; foreach ($policy as $build => $when) { $time = strtotime((string) $when); if ($time !== false && $time < strtotime('+100 years')) { $dates[(string) $build] = date('Y-m-d H:i:s', $time); } } return $dates; } private function extract(string $text): array { if (preg_match_all(self::ARTIFACT, $text, $matches, PREG_SET_ORDER) === false) { return []; } $refs = []; foreach ($matches as $match) { $build = $match[1]; $refs[$build] = [ 'build' => $build, 'ref' => $match[1] . '-' . $match[2], 'url' => self::LISTING . $match[1] . '-' . $match[2] . '/fx.tar.xz', ]; } return $refs; } } 